import { isHidden } from "./is-hidden.js"; // 末段 dot = 隐藏（.trash/.backup/.<appId>/任意 dot 项不进列举）
import { reportStoreError } from "./error-handling.js"; // 全接但分级：静默 swallow 也 funnel（不改控制流）
// 便利判定：**单一来源=syncState**，纯函数，**别在 Item 上加 cached/dirty 字段**（多一个字段=多一条下游越狱路径）。
/** 有本地副本 → 离线可读。 */
export function isCached(s) { return s !== "cloud-only"; }
/** 有未推本地编辑 → 永不被驱逐。 */
export function isDirty(s) {
    return s === "unpushed" || s === "conflict" || s === "float" || s === "ghost";
}
// ── 纯分类器（零 IO，可穷举单测）：一个 path 的原始事实 → syncState ──────────────────────
//   authoritative 分两级（对齐 reconcile 的失败-fetch 守卫）：
//     cloudReachable      = 拿到了云列表（在线 ∧ 登录 ∧ listAll 没抛错）——决定「云轴可不可解析」
//     absenceAuthoritative= 且 complete=true——决定「没看到=真没了」是否可信（partial 里缺失≠云端真没了，绝不据此判 gone）
export function classifySyncState(f) {
    if (!f.hasLocal)
        return "cloud-only"; // union 保证：到这一定 hasCloud
    // ── 本地有副本 ────────────────────────────────────────────────
    if (!f.cloudReachable) { // 离线/登出：云轴不可知 → 按谱系塌（2026-08-19 user 拍板）
        if (f.dirty)
            return f.everSynced ? "unpushed" : "float";
        // everSynced=谱系在案 → 显 synced（=「已留离线」语义；与下方 partial-absence 保守显 synced 同精神，
        // 回线后若云端动过自然纠偏成 newer-on-cloud）。原「一律塌 local-only」把已钉文件反向谎报成
        // 「从没上过云的真本地文件」——BR 真机战报打回（曾经的「别谎报 synced」注释被此案 supersede）。
        return f.everSynced ? "synced" : "local-only";
    }
    // ── cloudReachable ───────────────────────────────────────────
    if (f.hasCloud) { // 云端确实有（可信，无关 complete）
        const moved = f.cloudMoved || !f.everSynced; // 没 baseline(!everSynced 却撞上云端同名) 也当「云端有别的版本」
        if (moved)
            return f.dirty ? "conflict" : "newer-on-cloud";
        return f.dirty ? "unpushed" : "synced";
    }
    // ── 云列表里没有 ──────────────────────────────────────────────
    if (!f.everSynced)
        return f.dirty ? "float" : "local-only"; // 从没 synced = 真本地新文件，云端本就没有
    if (!f.absenceAuthoritative)
        return f.dirty ? "unpushed" : "synced"; // partial：没看到≠没了 → 保守显示「仍在」
    // 真 cloud-gone：dirty→👻ghost（绝不删）；clean 孤儿→防抖 grace 内显 pendingGone、grace 后被 reconcile trash 掉即从列表消失，否则 local-only。
    if (f.dirty)
        return "ghost";
    return f.pendingGone ? "pendingGone" : "local-only";
}
export const toMs = (v) => {
    if (v == null)
        return undefined;
    if (typeof v === "number")
        return v;
    const t = Date.parse(v);
    return Number.isFinite(t) ? t : undefined;
};
export function createListing(cfg) {
    const isHiddenAny = (n) => isHidden(n) || !!cfg.hidden?.(n);
    const { cloud, local, head, pendingFolders, isPendingGone, pendingFolderDeletions } = cfg;
    // 一个 path 的原始事实 → Item（cloud/local 两轴 + head → classifier）。listAllItems 与 listFolder 共用。
    function classifyPath(path, cf, hasLocal, cloudReachable, absenceAuthoritative, localStat) {
        const hasCloud = cf != null;
        const seen = head.seenBase(path);
        const everSynced = seen != null;
        const cloudMoved = hasCloud && cf.eTag !== seen;
        const dirty = head.isDirtyAnywhere(path); // 徽章答的是「这台设备有没有未推字节」（全局），不是本 tab 谱系
        const syncState = classifySyncState({
            hasLocal, hasCloud, everSynced, cloudMoved,
            dirty,
            cloudReachable, absenceAuthoritative,
            pendingGone: isPendingGone?.(path),
        });
        // size：云端有就用云端（authoritative），否则用本地缓存记录 → 离线 / 云端帧到达前也不显 0B/1970。
        // 时间（0.11.2，user 2026-08-31 拍板方案③）：**本地领先（dirty=有未推字节）才显本地时间，否则显云端时间**。
        //   以前一律云端优先：推云失败后本地一直在存、云端停在上次成功推 → tile 时间「倒退三小时」像没保存（案发 2026-08-31）。
        //   不用 max(cloud, local)：local.updatedAt 在 pull/自动缓存时也刷新，只打开看过的画会显「刚刚」——更骗人。
        //   判据与 badge 同源（dirty）：badge 说「未推」时间就是你本地最后一存；badge 说「已同步」时间就是云端那份；
        //   跨设备 B 机不 dirty → 云端时间正确。仅影响显示，不进任何同步/冲突判断（no-timestamps 红线不动）。
        const lastModified = dirty ? (localStat?.updatedAt ?? cf?.lastModified) : (cf?.lastModified ?? localStat?.updatedAt);
        return { path, syncState, size: cf?.size ?? localStat?.size, lastModified };
    }
    // 本地项的轻量元信息（size+updatedAt），批量取 → classifyPath 给本地项填尺寸/时间。stat 缺（老 mock）→ 跳过。
    async function statLocal(keys) {
        const m = new Map();
        if (!local.stat)
            return m;
        await Promise.all([...keys].map(async (k) => { const s = await local.stat(k); if (s)
            m.set(k, s); }));
        return m;
    }
    // 单夹列举（**非递归**）——watchFolder 的每次快照。**per-folder 权威**：只列该夹直属子项、只判该夹内 path。
    //   guardrail（红线）：绝不据本夹的 listing 判**别夹**文件 cloud-gone——因为压根不看别夹的 local key（下面 startsWith(prefix) 门）。
    //   absenceAuthoritative = 这一夹 list() 没抛错（cloudRes.complete）；离线/登出 → cloudReachable=false → 塌到本地视角。
    //   opts（A3）：cloudPrefetched=复用调用方已拉的现场云帧（修「一次订阅打两遍 Graph」）；
    //   staleCloud=dir-index-cache 的上次云帧——**只追加 cloud-only 缺项 + 子夹**，不碰既有项的分类。
    async function listFolder(folder, ctx, opts) {
        const cloudRes = opts?.cloudPrefetched !== undefined
            ? opts.cloudPrefetched
            : (ctx.online && ctx.signedIn) ? await cloud.listFolder(folder).catch((e) => { reportStoreError(e, "log"); return null; }) : null;
        const cloudReachable = cloudRes != null;
        const absenceAuthoritative = cloudReachable && cloudRes.complete === true;
        const prefix = folder ? `${folder}/` : "";
        const cloudMap = new Map();
        // 身份 = **全名（c.name = toName(云端文件名)）**：明文 X.dat 恒等、加密 X.dat.zip 去尾 .zip → 都归一到 X.dat。
        //   本地 key（appKeys / 迁移后）也是全名 X.dat → 两轴按同一 key 归一；否则 cloud 与 local 分裂成两项、open 对不上
        //   （=0B/打开空白的根因，v390）。app 在边界用 sessionFileName 把裸 session 名转全名；encFileName 负责加密件的 .zip 追加。
        for (const c of cloudRes?.files ?? []) {
            if (isHiddenAny(c.name))
                continue;
            cloudMap.set(c.name, { eTag: c.eTag, size: c.size, lastModified: toMs(c.lastModifiedDateTime) });
        }
        // 本地：只看本夹前缀下的 key；直属文件 → 参与列举，更深的 → 记 immediate 子夹。隐藏项（末段 dot）全跳。
        const localDirect = new Set();
        const subfolders = new Set();
        for (const k of await local.appKeys()) {
            if (folder && !k.startsWith(prefix))
                continue;
            const rest = k.slice(prefix.length);
            if (!rest)
                continue;
            const slash = rest.indexOf("/");
            if (slash >= 0) {
                const sub = prefix + rest.slice(0, slash);
                if (!isHiddenAny(sub))
                    subfolders.add(sub);
            }
            else if (!isHiddenAny(k))
                localDirect.add(k);
        }
        for (const f of cloudRes?.folders ?? []) {
            if (!isHiddenAny(f))
                subfolders.add(f);
        } // 云端 immediate 子夹（含空夹）
        for (const p of pendingFolders?.() ?? []) { // 离线建的空夹：取本夹下的 immediate 段
            if (folder && !p.startsWith(prefix))
                continue;
            const rest = folder ? p.slice(prefix.length) : p;
            const seg = rest.includes("/") ? rest.slice(0, rest.indexOf("/")) : rest;
            if (seg && !isHiddenAny(seg))
                subfolders.add(prefix + seg);
        }
        const paths = new Set([...cloudMap.keys(), ...localDirect]);
        const localStats = await statLocal(localDirect);
        const items = [];
        for (const path of paths)
            items.push(classifyPath(path, cloudMap.get(path), localDirect.has(path), cloudReachable, absenceAuthoritative, localStats.get(path)));
        // ── stale 快照追加（A3，本地帧专用）：只补「两轴都没见过」的 cloud-only 缺项 + 子夹。────────
        //   既有项（本地有/现场云帧有）**绝不被 stale 数据改写分类**——保存后快照里的旧 eTag 若参与分类，
        //   会闪假 newer-on-cloud badge。追加项 badge 恒 cloud-only（上次所见如此；过时由云端帧纠偏）。
        //   直属 scope 守卫与 localDirect 同纪律（快照损坏/串夹也进不来别夹的项）。
        const stale = opts?.staleCloud != null;
        if (opts?.staleCloud) {
            for (const f of opts.staleCloud.files) {
                if (paths.has(f.name) || isHiddenAny(f.name))
                    continue;
                const rest = folder ? (f.name.startsWith(prefix) ? f.name.slice(prefix.length) : "") : f.name;
                if (!rest || rest.includes("/"))
                    continue; // 越界/非直属 → 丢
                items.push({ path: f.name, syncState: "cloud-only", size: f.size, lastModified: f.lastModified });
            }
            for (const sf of opts.staleCloud.folders)
                if (!isHiddenAny(sf))
                    subfolders.add(sf);
        }
        // **post-union 减去**离线排队待删的空夹（否则 remote frame / stale 快照每次把它从 folders 闪回）。
        for (const d of pendingFolderDeletions?.() ?? [])
            subfolders.delete(d);
        const snap = { path: folder, items, folders: [...subfolders], complete: absenceAuthoritative };
        if (stale)
            snap.stale = true;
        return snap;
    }
    async function listAllItems(ctx) {
        // 云那半：仅在线 ∧ 登录才取；抛错 → null（优雅降级，绝不 throw、绝不据此清本地）。
        const cloudRes = (ctx.online && ctx.signedIn) ? await cloud.listAll().catch((e) => { reportStoreError(e, "log"); return null; }) : null;
        const cloudReachable = cloudRes != null;
        const absenceAuthoritative = cloudReachable && cloudRes.complete === true;
        const cloudMap = new Map();
        for (const c of cloudRes?.files ?? []) {
            if (isHiddenAny(c.name))
                continue;
            cloudMap.set(c.name, { eTag: c.eTag, size: c.size, lastModified: toMs(c.lastModifiedDateTime) }); // 身份=session name（裸），见 listFolder 同处注释
        }
        const localSet = new Set((await local.appKeys()).filter((k) => !isHiddenAny(k)));
        const paths = new Set();
        for (const p of cloudMap.keys())
            paths.add(p);
        for (const p of localSet)
            paths.add(p);
        const localStats = await statLocal(localSet);
        const items = [];
        for (const path of paths)
            items.push(classifyPath(path, cloudMap.get(path), localSet.has(path), cloudReachable, absenceAuthoritative, localStats.get(path)));
        // folders = 云 folders(可达时) ∪ 本地 pending 空夹（离线建的）。去重 + 隐藏项（末段 dot）跳过。
        const folderSet = new Set();
        for (const f of cloudRes?.folders ?? [])
            if (!isHiddenAny(f))
                folderSet.add(f);
        for (const p of pendingFolders?.() ?? [])
            if (!isHiddenAny(p))
                folderSet.add(p);
        for (const d of pendingFolderDeletions?.() ?? [])
            folderSet.delete(d); // post-union 减去待删空夹
        return { items, folders: [...folderSet], complete: cloudReachable ? cloudRes.complete : false };
    }
    return { listAllItems, listFolder };
}
